import{c as e,Q as a,j as l,m as r}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"CreateCubeResGroup","description":"","frontmatter":{},"headers":[{"level":1,"title":"CreateCubeResGroup","slug":"createcuberesgroup"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/CreateCubeResGroup.md","filePath":"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/CreateCubeResGroup.md"}'),d={name:"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/CreateCubeResGroup.md"};function s(i,t,o,u,n,p){return a(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="createcuberesgroup" tabindex="-1">CreateCubeResGroup <a class="header-anchor" href="#createcuberesgroup" aria-label="Permalink to &quot;CreateCubeResGroup&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>快速创建CubeResGroupHandle对象，内部完成消息队列空间和同步事件分配。推荐使用该接口，避免使用CubeResGroupHandle的构造函数创建对象，出现不同对象的消息队列空间冲突、同步事件错误等情况。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;int groupID, class MatmulApiType, template &lt;class, class&gt; class CallBack, typename CubeMsgType&gt;</span></span>
<span class="line"><span>__aicore__ inline CubeResGroupHandle&lt;CubeMsgType&gt; CreateCubeResGroup(KfcWorkspace&amp; desc, uint8_t blockStart, uint8_t blockSize, uint8_t msgQueueSize, GM_ADDR tiling)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>groupID</td><td>用于表示Group的编号，int32取值范围。</td></tr><tr><td>MatmulApiType</td><td>定义的AIC计算对象类型。</td></tr><tr><td>CallBack</td><td>回调函数类，需要实现Init和Call两个接口。</td></tr><tr><td>CubeMsgType</td><td>用户自定义的消息结构体。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>desc</td><td>输入</td><td>KfcWorkspace，用于维护消息队列空间。</td></tr><tr><td>blockStart</td><td>输入</td><td>该CubeResGroupHandle在AIV视角下的起始AIC对应的序号，即AIC起始序号 * 2。例如，如果AIC起始序号为0，则填入0 * 2；如果为1，则填入1 * 2。</td></tr><tr><td>blockSize</td><td>输入</td><td>该CubeResGroupHandle在AIV视角下分配的Block个数，即实际的AIC个数*2。</td></tr><tr><td>msgQueueSize</td><td>输入</td><td>该CubeResGroupHandle分配的消息队列总数。</td></tr><tr><td>tiling</td><td>输入</td><td>AIC核计算所需tiling信息的地址。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>CubeResGroupHandle对象实例。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>假设芯片的AIV核数为x，那么blockStart + blockSize &lt;= x - 1, msgQueueSize &lt;= x。</li><li>每个AIC至少被分配1个msgQueue。</li><li>blockStart和blockSize必须为偶数。</li><li>使用该接口，UB空间末尾的1600B + sizeof(CubeMsgType)将被占用。</li><li>1个AIC只能属于1个CubeGroupHandle，即多个CubeGroupHandle的[blockStart / 2, blockStart / 2 + blockSize / 2]区间不能重叠。</li><li>不能和<a href="./../../../高阶API/矩阵计算/Matmul-Kernel侧接口/REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>接口同时使用。使用资源管理API时，用户自主管理AIC和AIV的核间通信，REGIST_MATMUL_OBJ内部是由框架管理AIC和AIV的核间通信，同时使用可能会导致通信消息错误等异常。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto handle = AscendC::CreateCubeResGroup&lt;GROUPID, MatmulApiType, MyCallbackFunc, CubeMsgBody&gt; (desc, BLOCKSTART, BLOCKSIZE, MSGQUEUESIZE, tilingGM);</span></span></code></pre></div>`,18)])])}const h=e(d,[["render",s]]);export{c as __pageData,h as default};
